import type { JsonObject } from "@prisma/client/runtime/client";
import { sendEmail } from "../actions/sendemail.js";

export async function handleSchedule(currentAction: any, zapRunDetails: any) {
    // 1. Get the recipient and email body template from the action metadata
    const to = (currentAction.metadata as JsonObject)?.to as string;
    const emailTemplateBody = (currentAction.metadata as JsonObject)?.body as string || "Hello! This is your scheduled notification triggered at {triggeredAt}.";

    // 2. Get the metadata generated by the background scheduler (e.g. triggeredAt time)
    const rawPayload = zapRunDetails?.metadata;
    const schedulePayload = typeof rawPayload === 'string' ? JSON.parse(rawPayload) : rawPayload;

    const triggeredAt = schedulePayload?.triggeredAt ? new Date(schedulePayload.triggeredAt).toLocaleString() : new Date().toLocaleString();
    const cronExpr = schedulePayload?.cronExpr || "Custom Schedule";

    if (!to) {
        console.log("Skipping scheduled email: No target email address found in action metadata.");
        return;
    }

    // 3. Replace placeholders with actual schedule context
    const finalEmailBody = emailTemplateBody
        .replace("{triggeredAt}", triggeredAt)
        .replace("{cronExpr}", cronExpr);

    console.log("Sending out scheduled notification email to:", to);

    // 4. Dispatch the email
    await sendEmail({
        to,
        subject: `[Flowify] Scheduled Task Executed (${triggeredAt})`,
        text: finalEmailBody
    });
}